<?php
$isEdit = $mode === 'edit';
$action = $isEdit ? url('records-update', ['id' => (int) ($record['id'] ?? 0)]) : url('records-create');
$val = static function (string $key, mixed $default = '') use ($record): string {
    return e(old($key, $record[$key] ?? $default));
};
?>
<div class="page-heading"><div><p class="eyebrow">FORM DATA</p><h1><?= $isEdit ? 'Edit data' : 'Tambah data baru' ?></h1><p class="muted">Isi semua field wajib dan periksa validasi sebelum menyimpan.</p></div><a class="btn btn-ghost" href="<?= e(url('records')) ?>">← Kembali ke daftar</a></div>
<div class="form-layout"><section class="panel form-panel"><div class="panel-heading"><div><h2>Informasi data</h2><p>Field dengan tanda * wajib diisi.</p></div><span class="step-badge">01 / DATA</span></div>
<form method="post" action="<?= e($action) ?>" class="form-grid" novalidate>
    <?= csrf_field() ?>
    <div class="field"><label for="record_code">Kode data</label><?php if ($isEdit): ?><input id="record_code" name="record_code" value="<?= $val('record_code') ?>" maxlength="50" pattern="[A-Za-z0-9._-]+" required aria-describedby="record_code_help"><small id="record_code_help">Maksimal 50 karakter. Huruf, angka, titik, strip, underscore.</small><?php else: ?><input id="record_code" type="text" value="(otomatis dibuat sistem)" disabled><input type="hidden" name="record_code" value=""><small id="record_code_help">Kode akan dibuat otomatis oleh sistem.</small><?php endif; ?><?php if (isset($errors['record_code'])): ?><small class="field-error"><?= e($errors['record_code']) ?></small><?php endif; ?></div>
    <div class="field"><label for="name">Nama data <span>*</span></label><input id="name" name="name" value="<?= $val('name') ?>" maxlength="120" required><?php if (isset($errors['name'])): ?><small class="field-error"><?= e($errors['name']) ?></small><?php endif; ?></div>
    <div class="field"><label for="category">Kategori <span>*</span></label><input id="category" name="category" value="<?= $val('category') ?>" maxlength="80" required><?php if (isset($errors['category'])): ?><small class="field-error"><?= e($errors['category']) ?></small><?php endif; ?></div>
    <div class="field"><label for="numeric_value">Nilai angka / jumlah <span>*</span></label><input id="numeric_value" name="numeric_value" type="number" min="0" max="999999999999.99" step="0.01" value="<?= $val('numeric_value', '0') ?>" required><?php if (isset($errors['numeric_value'])): ?><small class="field-error"><?= e($errors['numeric_value']) ?></small><?php endif; ?></div>
    <div class="field field-full"><label for="description">Keterangan</label><textarea id="description" name="description" rows="4" maxlength="1000" placeholder="Informasi tambahan (opsional)"><?= $val('description') ?></textarea><small>Maksimal 1.000 karakter.</small><?php if (isset($errors['description'])): ?><small class="field-error"><?= e($errors['description']) ?></small><?php endif; ?></div>
    <div class="field"><label for="status">Status <span>*</span></label><select id="status" name="status" required><option value="active" <?= $val('status', 'active') === 'active' ? 'selected' : '' ?>>Aktif</option><option value="inactive" <?= $val('status') === 'inactive' ? 'selected' : '' ?>>Nonaktif</option></select><?php if (isset($errors['status'])): ?><small class="field-error"><?= e($errors['status']) ?></small><?php endif; ?></div>
    <div class="form-actions field-full"><a class="btn btn-ghost" href="<?= e(url('records')) ?>">Batal</a><button class="btn btn-primary" type="submit"><?= $isEdit ? 'Simpan perubahan' : 'Simpan data' ?> <span>→</span></button></div>
</form></section><aside class="form-aside"><div class="aside-icon">✦</div><h3>Checklist sebelum simpan</h3><ul><li>Kode data tidak boleh duplikat.</li><li>Field wajib sudah terisi.</li><li>Nilai angka tidak boleh negatif.</li><li>Periksa kembali status dan keterangan.</li></ul><div class="aside-note"><strong>Untuk tugas berbeda?</strong><p>Ganti nama field, tipe data, constraint, aturan validasi, dan label sesuai spesifikasi penguji. Lihat docs/PANDUAN-ADAPTASI.md.</p></div></aside></div>
